found = []
for line in lines:
    for pat, msg in SIGNATURES:
        m = re.search(pat, line, re.I)
        if not m: continue
        if msg is None:
            done, total = int(m.group(1)), int(m.group(2))
            if done < total: msg = f"partial offload {done}/{total} layers: model split between GPU and CPU"
            else: continue
        if msg not in found: found.append(msg)
return found

causes = []
if obs["processor"] == "100% CPU" and obs.get("has_gpu"): causes.append("model on CPU although a GPU exists")
elif "CPU/GPU" in obs["processor"]: causes.append("model split between CPU and GPU")
if obs["load_s"] > 5: causes.append("cold start: model loaded for this request")
if obs["prompt_tokens"] > 4000 and obs["prompt_tps"] < 500: causes.append("long prompt processed slowly")
if obs["tps"] < 0.5 * obs["expected_tps"] and not causes: causes.append("below expectation with no obvious cause: check thermals and other GPU load")
return causes or ["speed as expected"]

issues = []
leaked = [t for t in LEAKS if t in output]
if leaked: issues.append("special tokens in output (" + ", ".join(leaked) + "): chat template mismatch")
if re.search(r"(?im)^\s*(user|human)\s*:", output): issues.append("model writes the user's turn: missing stop sequence")
return issues

steps = []
for f in findings:
    key = next((k for k in PLAYBOOK if f.startswith(k) or f.endswith(k)), None)
    for s in PLAYBOOK.get(key, ["record the symptom and search the troubleshooting docs"]):
        if s not in steps: steps.append(s)
return steps
